class NomBillete extends BaseNomBillete
{

    public static function obtenerListadoBillete($inicio = 0, $limite = 1000)
    {
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomBillete')
            ->limit($limite)
            ->offset($inicio)
            ->orderBy('orden ASC')
            ->fetchArray():
        $query->from('NomBillete')
            ->orderBy('orden ASC')
            ->fetchArray();
        return $result;
    }

    public static function cantBilletes()
    {
        $sql = Doctrine_Query::create();
        return $sql->select('count(idbillete) as cantidad')
                ->from('NomBillete')
                ->fetchOne()
                ->cantidad;
    }

    public static function obtenerObjBilleteDadoId($idbillete)
    {
        return Doctrine::getTable('NomBillete')->find($idbillete);
    }

    public function obtenerDenominacion($idbillete)
    {
        $sql = Doctrine_Query::create();
        return $sql->select('denominacion')
            ->from('NomBillete')
            ->where('idbillete = ?', array($idbillete))
            ->fetchOne()
            ->denominacion;
    }

    public function obtenerBilletesMismaDenominacion($denominacion, $idmoneda)
    {
        $sql = Doctrine_Query::create();
        return $sql->select('idbillete')
            ->from('NomBillete')
            ->where('denominacion = ? and idmoneda = ?', array($denominacion, $idmoneda))
            ->fetchArray();
    }

    public function obtenerBilletesMismoOrden($orden, $idmoneda)
    {
        $sql = Doctrine_Query::create();
        return $sql->select('idbillete')
            ->from('NomBillete')
            ->where('orden = ? and idmoneda = ?', array($orden, $idmoneda))
            ->fetchArray();
    }

    public function obtenerDenominacionMoneda($idmoneda)
    {
        $sql = "select codigoiso from mod_datosmaestros.nom_moneda where idmoneda = ? ";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        return $conn->fetchAll($sql, array($idmoneda));
    }

    public function obtenerMonedaXCodigoIso($codigoiso)
    {
        $sql = "select * from mod_datosmaestros.nom_moneda where codigoiso ilike '%$codigoiso%'";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        return $conn->fetchAll($sql);
    }

    public function obtenerBilleteActivo($idbillete)
    {
        $sql = Doctrine_Query::create();
        return $sql->select('activo')
            ->from('NomBillete')
            ->where('idbillete = ?', array($idbillete))
            ->fetchOne()
            ->activo;
    }
}
